$base = "D:\repository"
$targets = @('\.workbuddy', '\.cursor', '\.claude', '\.codeium', '\.aider', '\.windsurf', '\.gemini', '\.continue', '\.roo', '\.cline', '\.kilocode', '\.github', '\.vscode', '\.idea', '\.agent', '\.zed', '\.trae', '\.devin', '\.sourcegraph', '\.qoder', '\.augment', '\.cody')
# find all directories matching any target, excluding .git internals
$res = @()
Get-ChildItem -Path $base -Recurse -Directory -ErrorAction SilentlyContinue | ForEach-Object {
    $name = $_.Name
    foreach ($t in $targets) {
        if ($name -match "^$t$") {
            # exclude things inside .git
            if ($_.FullName -notmatch '\\\.git\\') {
                $res += [PSCustomObject]@{ Dir = $_.FullName; Match = $name }
            }
        }
    }
}
$res | Sort-Object Dir | Format-Table -AutoSize | Out-String -Width 300

$base = "D:\repository"
$targets = @('\.workbuddy', '\.cursor', '\.claude', '\.codeium', '\.aider', '\.windsurf', '\.gemini', '\.continue', '\.roo', '\.cline', '\.kilocode', '\.vscode', '\.idea', '\.agent', '\.zed', '\.trae', '\.devin', '\.sourcegraph', '\.qoder', '\.augment', '\.cody')
$res = @()
Get-ChildItem -Path $base -Recurse -Directory -ErrorAction SilentlyContinue | Where-Object {
    $_.FullName -notmatch '\\node_modules\\' -and $_.FullName -notmatch '\\\.git\\'
} | ForEach-Object {
    foreach ($t in $targets) {
        if ($_.Name -match "^$t$") {
            $res += [PSCustomObject]@{ Repo = ($_.FullName -replace [regex]::Escape($base)+'\\','' -split '\\')[0]; Dir = $_.FullName; Match = $name }
        }
    }
}
$res | Group-Object Repo | Sort-Object Name | ForEach-Object {
    Write-Output "=== $($_.Name) ==="
    $_.Group | Select-Object -ExpandProperty Dir | Sort-Object
    Write-Output ""
}

$base = "D:\repository"
$dirs = @(
 '基金面板\.workbuddy',
 '门户\.workbuddy',
 '苏州市房地产监测V3\.workbuddy',
 '苏住房后端\.workbuddy',
 '无锡市区G\.workbuddy',
 '苏州市房地产监测V3\.cursor',
 '淮安物管\.trae',
 '惠山小程序\.trae',
 '家园区一网通办\.trae'
)
foreach ($d in $dirs) {
    $repo = ($d -split '\\')[0]
    $path = $d -replace "^$repo\\",''
    $full = Join-Path $base $d
    $exists = Test-Path $full
    $tracked = $false
    if ($exists) {
        try { git -C (Join-Path $base $repo) ls-files --error-unmatch $path 2>$null | Out-Null; $tracked = $? } catch { $tracked = $false }
    }
    Write-Output "$d | exists=$exists | tracked=$tracked"
}
# check if zhi2-web-admin is a submodule in a couple repos
Write-Output "--- submodule check ---"
foreach ($repo in @('产品2.0','保障房G','门户','苏住房G')) {
    $g = Join-Path $base $repo
    $r = git -C $g submodule status 2>$null
    if ($r) { Write-Output "$repo submodules:"; $r | ForEach-Object { Write-Output "   $_" } } else { Write-Output "$repo: (no submodule / not a repo)" }
}

$base = "D:\repository"
$dirs = @(
 '基金面板\.workbuddy',
 '门户\.workbuddy',
 '苏州市房地产监测V3\.workbuddy',
 '苏住房后端\.workbuddy',
 '无锡市区G\.workbuddy',
 '苏州市房地产监测V3\.cursor',
 '淮安物管\.trae',
 '惠山小程序\.trae',
 '家园区一网通办\.trae'
)
foreach ($d in $dirs) {
    $repo = ($d -split '\\')[0]
    $path = $d -replace "^$repo\\",''
    $full = Join-Path $base $d
    $exists = Test-Path $full
    $tracked = $false
    if ($exists) {
        git -C (Join-Path $base $repo) ls-files --error-unmatch $path 2>$null | Out-Null
        $tracked = $LASTEXITCODE -eq 0
    }
    Write-Output "$d | exists=$exists | tracked=$tracked"
}
Write-Output "--- submodule check ---"
foreach ($repo in @('产品2.0','保障房G','门户','苏住房G')) {
    $g = Join-Path $base $repo
    $r = git -C $g submodule status 2>$null
    if ($r) {
        Write-Output "$repo submodules:"
        $r | ForEach-Object { Write-Output "   $_" }
    } else {
        Write-Output "${repo}: no submodule or not a repo"
    }
}

$base = "D:\repository"
$ops = @(
  @{repo='基金面板'; dir='.workbuddy'; tracked=$false}
  @{repo='门户'; dir='.workbuddy'; tracked=$false}
  @{repo='苏州市房地产监测V3'; dir='.workbuddy'; tracked=$true}
  @{repo='苏州市房地产监测V3'; dir='.cursor'; tracked=$true}
  @{repo='无锡市区G'; dir='.workbuddy'; tracked=$true}
  @{repo='淮安物管'; dir='.trae'; tracked=$false}
  @{repo='惠山小程序'; dir='.trae'; tracked=$true}
  @{repo='家园区一网通办'; dir='.trae'; tracked=$false}
)

$groups = @{}
foreach ($op in $ops) {
  if (-not $groups.ContainsKey($op.repo)) { $groups[$op.repo] = @() }
  $groups[$op.repo] += $op
}

foreach ($repo in $groups.Keys) {
  $g = Join-Path $base $repo
  $isRepo = Test-Path (Join-Path $g ".git")
  $gi = Join-Path $g ".gitignore"
  $giContent = if ($isRepo -and (Test-Path $gi)) { @(Get-Content $gi -Encoding utf8) } else { @() }
  $added = @()
  foreach ($op in $groups[$repo]) {
    $dir = $op.dir
    $full = Join-Path $g $dir
    if (Test-Path $full) {
      if ($isRepo -and $op.tracked) { git -C $g rm -r --quiet -- $dir 2>&1 | Out-Null }
      Remove-Item $full -Recurse -Force -ErrorAction SilentlyContinue
      Write-Output "REMOVED $repo/$dir (tracked=$($op.tracked))"
    } else { Write-Output "ABSENT  $repo/$dir" }
    if ($isRepo) {
      $base2 = $dir.TrimStart('.')
      $has = ($giContent | Where-Object { $_ -match [regex]::Escape('.'+$base2) }).Count -gt 0
      if (-not $has) { $added += ($dir + '/'); $giContent += ($dir + '/') }
    }
  }
  if ($isRepo -and $added.Count -gt 0) {
    if (-not (Test-Path $gi)) { "" | Out-File -Encoding utf8 $gi }
    Add-Content -Path $gi -Value "" -Encoding utf8
    Add-Content -Path $gi -Value "# AI coding agent / editor tooling" -Encoding utf8
    foreach ($a in $added) { Add-Content -Path $gi -Value $a -Encoding utf8 }
    Write-Output "GITIGNORE+ $repo : $($added -join ', ')"
  }
}
Write-Output "=== DONE ==="

$base = "D:\repository"
$targets = @('\.workbuddy', '\.cursor', '\.trae')
$found = @()
Get-ChildItem -Path $base -Recurse -Directory -ErrorAction SilentlyContinue | Where-Object {
    $_.FullName -notmatch '\\node_modules\\' -and $_.FullName -notmatch '\\\.git\\'
} | ForEach-Object {
    foreach ($t in $targets) {
        if ($_.Name -match "^$t$") {
            $found += ($_.FullName -replace [regex]::Escape($base)+'\\','')
        }
    }
}
Write-Output "Remaining .workbuddy/.cursor/.trae (excluding node_modules/.git):"
if ($found.Count -eq 0) { Write-Output "  (none)" } else { $found | Sort-Object | ForEach-Object { Write-Output "  $_" } }

$base = "D:\repository"
$repos = @('苏州市房地产监测V3','无锡市区G','惠山小程序','淮安物管','家园区一网通办')
$msg = "chore: 移除 AI 编程工具目录(.workbuddy/.cursor/.trae)并加入 .gitignore"
foreach ($repo in $repos) {
  $g = Join-Path $base $repo
  Write-Output "### $repo"
  git -C $g commit -m $msg 2>&1 | ForEach-Object { Write-Output "  $_" }
  git -C $g push 2>&1 | ForEach-Object { Write-Output "  $_" }
  Write-Output ""
}
